// Tank asset registry: hulls.json / turrets.json.
//
// Both manifests are generated by scripts/build-manifests.mjs and list
// ALREADY-RESOLVED URLs. Nothing here builds a path from an id, guesses a
// letter case or probes alternative file names — if a manifest entry is
// missing, that is a build error, not something to paper over at runtime.

export interface TankPartFiles {
  /** .3ds mesh — the hull mesh carries the "track" submaterial. */
  mesh: string;
  lightmap: string;
  details: string;
}

export interface TankPartEntry {
  id: string;
  mods: Record<string, TankPartFiles>;
  thumbnail?: string;
}

/** One garage paint from paints.json (see scripts/build-manifests.mjs). */
export interface PaintEntry {
  id: string;
  /** Paint layer tiled under the lightmap. */
  image: string;
  /** Garage swatch for the menu; absent for a couple of paints in the dump. */
  preview?: string;
}

export interface TankAssetRegistry {
  hulls: Map<string, TankPartEntry>;
  turrets: Map<string, TankPartEntry>;
  paints: Map<string, PaintEntry>;
}

/**
 * Manifest paths are site-absolute ("/hulls/..."). Qualify them with the page
 * origin so every consumer holds a complete URL — a bare "maps/x.xml" would be
 * resolved relative to the current path, and "//maps/x.xml" would be read as a
 * host name.
 */
/**
 * Where the game's static assets live.
 *
 *  - dev: the Vite public dir under the app's own base (BASE_URL '/game/');
 *  - prod: the R2 store behind the worker, via VITE_ASSET_BASE='/assets/'.
 *
 * Site-absolute inputs like '/turrets/x.png' are REBASED under this prefix;
 * fully-qualified URLs pass through untouched (manifests may already carry
 * them after loadMapRegistry/loadTankAssetRegistry qualified their entries).
 */
const ASSET_BASE: string =
  (import.meta.env.VITE_ASSET_BASE as string | undefined) ?? import.meta.env.BASE_URL ?? '/';

/**
 * Site-absolute asset path -> URL. Overridable: a host application (the
 * mobile PWA in apps/mobile) installs its own resolver so that some paths
 * are served from the app bundle and the rest from a remote asset host.
 * Null = the build-time ASSET_BASE behaviour below.
 */
export type AssetUrlResolver = (path: string) => string;
let resolver: AssetUrlResolver | null = null;

/**
 * Installs a resolver for every assetUrl() call made from now on. Several
 * engine modules call assetUrl() at import time (HitEffects, TankAudio,
 * bootstrap...), so a host must install this BEFORE importing them — see
 * apps/mobile/src/main.ts, which imports the engine lazily for that reason.
 */
export function setAssetUrlResolver(next: AssetUrlResolver | null): void {
  resolver = next;
}

export function assetUrl(path: string): string {
  if (/^[a-z][a-z0-9+.-]*:/i.test(path)) {
    return path; // already absolute (http:, data:, blob:)
  }
  if (resolver != null) {
    return resolver(path);
  }
  return new URL(path.replace(/^\//, ''), new URL(ASSET_BASE, window.location.origin)).href;
}

async function loadManifest(url: string, key: 'hulls' | 'turrets'): Promise<Map<string, TankPartEntry>> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to load ${url}: HTTP ${response.status}`);
  }
  const data = (await response.json()) as Record<string, TankPartEntry[]>;
  const entries = data[key];
  if (!Array.isArray(entries)) {
    throw new Error(`${url}: expected a "${key}" array`);
  }
  return new Map(
    entries.map((entry) => [
      entry.id,
      {
        ...entry,
        mods: Object.fromEntries(
          Object.entries(entry.mods).map(([mod, files]) => [
            mod,
            { mesh: assetUrl(files.mesh), lightmap: assetUrl(files.lightmap), details: assetUrl(files.details) },
          ]),
        ),
        ...(entry.thumbnail != null ? { thumbnail: assetUrl(entry.thumbnail) } : {}),
      },
    ]),
  );
}

/**
 * Garage paints. A missing manifest is not fatal: the tank falls back to the
 * team colour, so the game still runs on an asset tree without paints.
 */
async function loadPaints(url: string): Promise<Map<string, PaintEntry>> {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    const data = (await response.json()) as { paints?: PaintEntry[] };
    if (!Array.isArray(data.paints)) {
      throw new Error('expected a "paints" array');
    }
    return new Map(
      data.paints.map((entry) => [
        entry.id,
        {
          ...entry,
          image: assetUrl(entry.image),
          ...(entry.preview != null ? { preview: assetUrl(entry.preview) } : {}),
        },
      ]),
    );
  } catch (error) {
    console.warn(`TankAssets: ${url} unavailable — paints disabled`, error);
    return new Map();
  }
}

export async function loadTankAssetRegistry(): Promise<TankAssetRegistry> {
  const [hulls, turrets, paints] = await Promise.all([
    loadManifest(assetUrl('/hulls.json'), 'hulls'),
    loadManifest(assetUrl('/turrets.json'), 'turrets'),
    loadPaints(assetUrl('/paints.json')),
  ]);
  return { hulls, turrets, paints };
}

/** Files for one part + modification. Throws with a precise message if absent. */
export function resolvePart(
  registry: Map<string, TankPartEntry>,
  kind: 'hull' | 'turret',
  id: string,
  modification: string,
): TankPartFiles {
  const entry = registry.get(id);
  if (entry == null) {
    throw new Error(`Unknown ${kind} "${id}" (known: ${[...registry.keys()].join(', ')})`);
  }
  const files = entry.mods[modification];
  if (files == null) {
    throw new Error(
      `${kind} "${id}" has no modification "${modification}" (has: ${Object.keys(entry.mods).join(', ')})`,
    );
  }
  return files;
}
